def _validate_trans_variables(
    self, variables: t.Dict[str, nodes.Expr], parser: "Parser", lineno: int
) -> None:
    """Validate all variables used in a translation block."""
    for name, expr in variables.items():
        if not name.isidentifier() or keyword.iskeyword(name):
            parser.fail(
                f"Invalid variable name {name!r}: translation variables "
                "must be valid Python identifiers.",
                lineno,
            )
        if name in GETTEXT_FUNCTIONS:
            parser.fail(
                f"Variable name {name!r} conflicts with translation function "
                "names and cannot be used as a translation variable.",
                lineno,
            )
        self._validate_trans_expression(name, expr, parser, lineno)

def _validate_trans_expression(
    self, name: str, expr: nodes.Expr, parser: "Parser", lineno: int
) -> None:
    """Validate a single translation variable expression."""
    if isinstance(
        expr,
        (
            nodes.Const,
            nodes.Name,
            nodes.Getattr,
            nodes.Filter,
            nodes.Test,
        ),
    ):
        return
    if isinstance(expr, nodes.Call):
        if not isinstance(expr.node, nodes.Name):
            parser.fail(
                f"Variable {name!r} uses an incompatible expression: only "
                "simple function calls are allowed in translation contexts.",
                lineno,
            )
        return
    parser.fail(
        f"Variable {name!r} uses an incompatible expression: template data "
        "and complex nested expressions are not allowed in translation contexts.",
        lineno,
    )

class ConditionalI18nExtension(Extension):
    """Adds a ``ctrans`` tag that conditionally renders translations based on
    a runtime boolean condition, with mandatory fallback content.

    .. code-block:: html+jinja

        {% ctrans use_i18n, count %}Hello {{ name }}{% pluralize %}
        Hello you all{% fallback %}Fallback!{% endctrans %}
    """

    tags = {"ctrans"}

    def parse(self, parser: "Parser") -> t.Union[nodes.Node, t.List[nodes.Node]]:
        lineno = next(parser.stream).lineno

        condition = parser.parse_expression()

        variables: t.Dict[str, nodes.Expr] = {}
        plural_expr: t.Optional[nodes.Expr] = None
        trimmed: t.Optional[bool] = None

        seen_comma = False
        first = True
        while parser.stream.current.type != "block_end":
            if not first:
                if parser.stream.current.type == "comma":
                    next(parser.stream)
                else:
                    parser.stream.expect("comma")

            # skip colon for python compatibility
            if parser.stream.skip_if("colon"):
                break

            if parser.stream.current.type == "name":
                token = parser.stream.current
            else:
                parser.fail("expected a variable name", parser.stream.current.lineno)

            if token.value in variables:
                parser.fail(
                    f"translatable variable {token.value!r} defined twice.",
                    token.lineno,
                    exc=TemplateAssertionError,
                )

            if parser.stream.current.type == "assign":
                next(parser.stream)
                variables[token.value] = var = parser.parse_expression()
            elif trimmed is None and token.value in ("trimmed", "notrimmed"):
                trimmed = token.value == "trimmed"
            else:
                variables[token.value] = var = nodes.Name(token.value, "load")

            if plural_expr is None:
                if isinstance(var, nodes.Call):
                    plural_expr = nodes.Name("_trans", "load")
                    variables[token.value] = plural_expr
                else:
                    plural_expr = var

            first = False
            seen_comma = True

        parser.stream.expect("block_end")

        # Parse the singular block (translatable content).
        singular_names, singular = self._parse_block(parser, "fallback")
        referenced = set(singular_names)
        if plural_expr is None and singular_names:
            plural_expr = nodes.Name(singular_names[0], "load")

        # Optionally parse the pluralize block.
        plural = None
        have_plural = False
        if parser.stream.current.test("name:pluralize"):
            have_plural = True
            next(parser.stream)
            if parser.stream.current.type != "block_end":
                token = parser.stream.expect("name")
                if token.value not in variables:
                    parser.fail(
                        f"unknown variable {token.value!r} for pluralization",
                        token.lineno,
                        exc=TemplateAssertionError,
                    )
                plural_expr = variables[token.value]
            parser.stream.expect("block_end")
            plural_names, plural = self._parse_block(parser, "endctrans")
            referenced.update(plural_names)
        else:
            # The next token should be the fallback block.
            pass

        # Mandatory fallback block.
        if not parser.stream.current.test("name:fallback"):
            parser.fail(
                "expected 'fallback' block",
                parser.stream.current.lineno,
            )
        next(parser.stream)  # consume "fallback"
        if parser.stream.current.type != "block_end":
            parser.fail(
                "expected 'fallback' block to start with block end",
                parser.stream.current.lineno,
            )
        parser.stream.expect("block_end")
        fallback_names, fallback = self._parse_block(parser, "endctrans")
        referenced.update(fallback_names)
        next(parser.stream)  # consume endctrans

        if not have_plural:
            plural_expr = None

        for name in referenced:
            if name not in variables:
                variables[name] = nodes.Name(name, "load")

        if trimmed is None:
            trimmed = self.environment.policies.get("ext.i18n.trimmed", False)
        if trimmed:
            singular = self._trim_whitespace(singular)
            if plural is not None:
                plural = self._trim_whitespace(plural)
            fallback = self._trim_whitespace(fallback)

        node = self._make_conditional_node(
            condition, singular, plural, fallback, variables, plural_expr
        )
        node.set_lineno(lineno)
        return node

    def _parse_block(
        self, parser: "Parser", terminator: str
    ) -> t.Tuple[t.List[str], str]:
        """Parse until the next block tag with the given name."""
        referenced: t.List[str] = []
        buf: t.List[str] = []

        while True:
            if parser.stream.current.type == "data":
                buf.append(parser.stream.current.value.replace("%", "%%"))
                next(parser.stream)
            elif parser.stream.current.type == "variable_begin":
                next(parser.stream)
                name = parser.stream.expect("name").value
                referenced.append(name)
                buf.append(f"%({name})s")
                parser.stream.expect("variable_end")
            elif parser.stream.current.type == "block_begin":
                next(parser.stream)
                if parser.stream.current.test(f"name:{terminator}"):
                    break
                parser.fail(
                    "control structures in translatable sections are not allowed"
                )
            elif parser.stream.eos:
                parser.fail("unclosed conditional translation block")
            else:
                raise RuntimeError("internal parser error")

        return referenced, concat(buf)

    def _trim_whitespace(self, string: str, _ws_re: t.Pattern[str] = _ws_re) -> str:
        return _ws_re.sub(" ", string.strip())

    def _make_conditional_node(
        self,
        condition: nodes.Expr,
        singular: str,
        plural: t.Optional[str],
        fallback: str,
        variables: t.Dict[str, nodes.Expr],
        plural_expr: t.Optional[nodes.Expr],
    ) -> nodes.If:
        """Build an If node that renders translation or fallback."""
        newstyle = self.environment.newstyle_gettext  # type: ignore

        # Translation branch.
        if plural_expr is None:
            gettext = nodes.Name("gettext", "load")
            trans_node: nodes.Expr = nodes.Call(
                gettext, [nodes.Const(singular)], [], None, None
            )
        else:
            ngettext = nodes.Name("ngettext", "load")
            trans_node = nodes.Call(
                ngettext,
                [nodes.Const(singular), nodes.Const(plural), plural_expr],
                [],
                None,
                None,
            )

        if newstyle:
            for key, value in variables.items():
                trans_node.kwargs.append(nodes.Keyword(key, value))
        else:
            trans_node = nodes.MarkSafeIfAutoescape(trans_node)
            if variables:
                trans_node = nodes.Mod(
                    trans_node,
                    nodes.Dict(
                        [
                            nodes.Pair(nodes.Const(key), value)
                            for key, value in variables.items()
                        ]
                    ),
                )

        # Fallback branch: simple variable substitution.
        fb_node: nodes.Expr
        fb_vars = {name: value for name, value in variables.items()}
        if fb_vars:
            fb_expr: nodes.Expr = nodes.Const(fallback)
            fb_node = nodes.Mod(
                fb_expr,
                nodes.Dict(
                    [
                        nodes.Pair(nodes.Const(name), value)
                        for name, value in fb_vars.items()
                    ]
                ),
            )
        else:
            fb_node = nodes.Const(fallback)

        then_body = [nodes.Output([trans_node])]
        else_body = [nodes.Output([nodes.MarkSafeIfAutoescape(fb_node)] if newstyle else nodes.Output([fb_node])]
        # Fix: else_body should be a list of nodes
        else_body = [nodes.Output([fb_node])]

        return nodes.If(condition, then_body, else_body)


